def main():
    src = r"d:\drl_project\tourist_places\chennai_places.json"
    if os.path.exists(src):
        with open(src, encoding="utf-8") as f:
            existing = json.load(f)
    else:
        existing = []

    existing_ids = {p["id"] for p in existing}
    new_places = [p for p in EXTRA_PLACES if p["id"] not in existing_ids]
    all_places = existing + new_places

    out_dir = r"d:\drl_project\tourist_places"
    with open(os.path.join(out_dir, "chennai_places.json"), "w", encoding="utf-8") as f:
        json.dump(all_places, f, indent=2, ensure_ascii=False)
    pd.DataFrame(all_places).to_csv(os.path.join(out_dir, "chennai_places.csv"), index=False, encoding="utf-8")
    print(f"Total places: {len(all_places)} (added {len(new_places)} new)")

if __name__ == "__main__":
    main()
